/// <summary>
/// Exception thrown when a task state transition or operation is invalid.
/// </summary>
public class TaskStateException : TaskManagementDomainException
{
    public Guid TaskId { get; }

    public TaskStateException(Guid taskId, string message)
        : base("Task:InvalidState", message)
    {
        TaskId = taskId;
        WithData("taskId", taskId);
    }

    public static TaskStateException InvalidStatusTransition(Guid taskId, TaskStatusEnum currentStatus, TaskStatusEnum newStatus)
        => new(taskId, $"Cannot transition task from status '{currentStatus}' to '{newStatus}'")
            .WithData("currentStatus", currentStatus)
            .WithData("newStatus", newStatus);

    public static TaskStateException CannotCompleteWithPendingDependencies(Guid taskId)
        => new(taskId, "Cannot complete task because it has incomplete dependencies");

    public static TaskStateException TimeTrackingAlreadyStarted(Guid taskId)
        => new(taskId, "Time tracking is already in progress for this task");

    public static TaskStateException TimeTrackingNotStarted(Guid taskId)
        => new(taskId, "No time tracking session is in progress for this task");
}
