// File: NouAssist.Productivity.TaskProjectGTD.TaskDelegation/Domain.Shared/Policies/{Entity}Policies.cs
namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Shared.Policies
{
    /// <summary>
    /// Contains policies for {Entity} status transitions and validations.
    /// </summary>
    public static class {Entity}Policies
    {
        public static class StatusTransitionPolicy
        {
            private static readonly Dictionary<{Entity}Status, HashSet<{Entity}Status>> AllowedTransitions = new()
            {
                {
                    {Entity}Status.Draft, new HashSet<{Entity}Status>
                    {
                        {Entity}Status.Active,
                        {Entity}Status.Cancelled
                    } 
                }
            };

            public static bool CanTransition({Entity}Status current, {Entity}Status target)
            {
                return AllowedTransitions.TryGetValue(current, out var allowed) &&
                       allowed.Contains(target);
            }

            public static void ValidateTransition({Entity}Status current, {Entity}Status target)
            {
                if (!CanTransition(current, target))
                {
                    throw new {Entity}BusinessRuleViolationException(
                        "StatusTransition", 
                        $"Cannot transition from {current} to {target}"
                    );
                }
            }
        }
    }
}
```

