namespace NouAssist.Productivity.SocialCommunication.Analytics.Domain.Aggregates
{
    /// <summary>
    /// Represents the BlogPost aggregate root.
    /// </summary>
    [Table("AppBlogPosts")]
    public class BlogPostAggregate : FullAuditedAggregateRoot<Guid>, IMultiTenant
    {
        public Guid? TenantId { get; protected set; }
        public string Title { get; private set; }
        public BlogPostStatus Status { get; private set; }

        private readonly List<Comment> _comments;
        public IReadOnlyCollection<Comment> Comments => _comments.AsReadOnly();

        protected BlogPostAggregate() { }

        internal BlogPostAggregate(Guid id, string title, Guid? tenantId)
            : base(id)
        {
            TenantId = tenantId;
            SetTitle(title);
            Status = BlogPostStatus.Draft;
            _comments = new List<Comment>();
        }

        /// <summary>
        /// Sets the blog post title with validation.
        /// </summary>
        internal void SetTitle(string title)
        {
            Title = Check.NotNullOrWhiteSpace(
                title,
                nameof(title),
                maxLength: BlogPostConsts.MaxTitleLength
            );
        }

        /// <summary>
        /// Updates the status of the blog post.
        /// </summary>
        internal void UpdateStatus(BlogPostStatus newStatus)
        {
            BlogPostPolicies.StatusTransitionPolicy.ValidateTransition(Status, newStatus);
            Status = newStatus;
        }
    }
}
