namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Represents a monetary value.
    /// </summary>
    public class Money : ValueObject
    {
        public decimal Amount { get; private set; }
        public string Currency { get; private set; }

        private Money() { }

        public Money(decimal amount, string currency)
        {
            SetAmount(amount);
            SetCurrency(currency);
        }

        private void SetAmount(decimal amount)
        {
            if (amount < 0)
            {
                throw new BusinessException("Money:NegativeAmount", "Amount cannot be negative");
            }
            Amount = amount;
        }

        private void SetCurrency(string currency)
        {
            Currency = Check.NotNullOrWhiteSpace(currency, nameof(currency), maxLength: MoneyConsts.MaxCurrencyLength);
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return Amount;
            yield return Currency;
        }

        public static Money operator +(Money left, Money right)
        {
            if (left.Currency != right.Currency)
            {
                throw new BusinessException("Money:DifferentCurrencies", "Cannot add different currencies");
            }
            return new Money(left.Amount + right.Amount, left.Currency);
        }
    }
}
