namespace NouAssist.Productivity.SocialCommunication.Analytics.Domain.Specifications.Base
{
    /// <summary>
    /// Base specification for filtering {Entity} aggregates.
    /// </summary>
    public abstract class {Entity}SpecificationBase : Specification<{Entity}Aggregate>
    {
        protected virtual bool IgnoreTenantFilter { get; } = false;
        protected virtual bool IgnoreDeletedFilter { get; } = false;

        protected override void ApplyFilter(FilterBuilder<{Entity}Aggregate> builder)
        {
            if (!IgnoreTenantFilter)
            {
                builder.And(e => e.TenantId == CurrentTenant.Id);
            }

            if (!IgnoreDeletedFilter)
            {
                builder.And(e => !e.IsDeleted);
            }
        }
    }
}
