// File: NouAssist.Productivity.TaskProjectGTD.TaskDelegation/Domain/Services/{Entity}Manager.cs
namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Services
{
    /// <summary>
    /// Domain service for managing {Entity} aggregates.
    /// </summary>
    public class {Entity}Manager : DomainService, I{Entity}Manager
    {
        private readonly ILogger<{Entity}Manager> _logger;
        private readonly I{Entity}Repository _{entity}Repository;
        private readonly IDistributedEventBus _eventBus;

        public {Entity}Manager(
            ILogger<{Entity}Manager> logger,
            I{Entity}Repository {entity}Repository,
            IDistributedEventBus eventBus
        )
        {
            _logger = logger;
            _{entity}Repository = {entity}Repository;
            _eventBus = eventBus;
        }

        public async Task<{Entity}Aggregate> CreateAsync(
            string name,
            string description,
            CancellationToken cancellationToken = default
        )
        {
            try
            {
                _logger.LogInformation("Creating {Entity} with name: {Name}", name);

                var entity = new {Entity}Aggregate(
                    GuidGenerator.Create(),
                    name,
                    CurrentTenant.Id
                );

                await _{entity}Repository.InsertAsync(entity, autoSave: true, cancellationToken);

                await _eventBus.PublishAsync(
                    new {Entity}CreatedEvent
                    {
                        Id = entity.Id,
                        Name = entity.Name,
                        TenantId = entity.TenantId
                    },
                    cancellationToken: cancellationToken
                );

                return entity;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error creating {Entity} with name: {Name}", name);
                throw new {Module}DomainException("{Module}:{Entity}:CreateError", "An error occurred while creating the entity.", ex);
            }
        }

        public async Task<{Entity}Aggregate> UpdateStatusAsync(
            Guid id,
            {Entity}Status newStatus,
            CancellationToken cancellationToken = default
        )
        {
            try
            {
                _logger.LogInformation("Updating Status of {Entity} with Id: {Id} to: {Status}", id, newStatus);

                var entity = await _{entity}Repository.GetAsync(id, cancellationToken: cancellationToken);

                if (entity is null)
                {
                    throw new {Entity}NotFoundException(id);
                }

                entity.UpdateStatus(newStatus);

                await _{entity}Repository.UpdateAsync(entity, autoSave: true, cancellationToken);

                await _eventBus.PublishAsync(
                    new {Entity}UpdatedEvent
                    {
                        Id = entity.Id,
                        Name = entity.Name,
                        TenantId = entity.TenantId,
                        Status = entity.Status
                    },
                    cancellationToken: cancellationToken
                );

                return entity;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating status of {Entity} with Id: {Id} to: {Status}", id, newStatus);
                throw new {Module}DomainException("{Module}:{Entity}:UpdateStatusError", "An error occurred while updating the entity status.", ex);
            }
        }
    }
}
```

