namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Shared.Exceptions
{
    public class TaskAlreadyAssignedException : TaskDelegationDomainException
    {
        public Guid TaskId { get; }

        public TaskAlreadyAssignedException(Guid taskId)
            : base("TaskDelegation:TaskAlreadyAssigned", $"Task with ID {taskId} is already assigned.")
