namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    public class WorkloadIndicator : ValueObject
    {
        public int CurrentAssignedTasks { get; private set; }
        public TimeSpan TotalEstimatedTime { get; private set; }
        public TimeSpan AvailableTime { get; private set; }
        public double UtilizationRate { get; private set; }
        public Trend WorkloadTrend { get; private set; }
        public RiskLevel OverAllocationRisk { get; private set; }

        private WorkloadIndicator() { }

        public WorkloadIndicator(
            int currentAssignedTasks,
            TimeSpan totalEstimatedTime,
            TimeSpan availableTime,
            Trend workloadTrend)
        {
            if (currentAssignedTasks < 0)
                throw new BusinessException("WorkloadIndicator:InvalidTaskCount", "Current assigned tasks cannot be negative.");

            if (totalEstimatedTime < TimeSpan.Zero)
                throw new BusinessException("WorkloadIndicator:InvalidEstimatedTime", "Total estimated time cannot be negative.");

            if (availableTime < TimeSpan.Zero)
                throw new BusinessException("WorkloadIndicator:InvalidAvailableTime", "Available time cannot be negative.");

            CurrentAssignedTasks = currentAssignedTasks;
            TotalEstimatedTime = totalEstimatedTime;
            AvailableTime = availableTime;
            WorkloadTrend = workloadTrend;

            CalculateUtilizationRate();
            DetermineOverAllocationRisk();
        }

        private void CalculateUtilizationRate()
        {
            UtilizationRate = AvailableTime.TotalHours > 0 
                ? (TotalEstimatedTime.TotalHours / AvailableTime.TotalHours) * 100 
                : 100;
        }

        private void DetermineOverAllocationRisk()
        {
            OverAllocationRisk = UtilizationRate switch
            {
                <= 80 => RiskLevel.Low,
                <= 95 => RiskLevel.Medium,
                _ => RiskLevel.High
            };
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return CurrentAssignedTasks;
            yield return TotalEstimatedTime;
            yield return AvailableTime;
            yield return UtilizationRate;
            yield return WorkloadTrend;
            yield return OverAllocationRisk;
        }
    }
}

