namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    public class PerformanceMetrics : ValueObject
    {
        public double CompletionRate { get; private set; }
        public double OnTimeDelivery { get; private set; }
        public double QualityScore { get; private set; }
        public TimeSpan ResponseTime { get; private set; }
        public double EscalationRate { get; private set; }

        private PerformanceMetrics() { }

        public PerformanceMetrics(
            double completionRate,
            double onTimeDelivery,
            double qualityScore,
            TimeSpan responseTime,
            double escalationRate)
        {
            ValidateMetrics(
                completionRate,
                onTimeDelivery,
                qualityScore,
                responseTime,
                escalationRate
            );

            CompletionRate = completionRate;
            OnTimeDelivery = onTimeDelivery;
            QualityScore = qualityScore;
            ResponseTime = responseTime;
            EscalationRate = escalationRate;
        }

        private void ValidateMetrics(
            double completionRate,
            double onTimeDelivery,
            double qualityScore,
            TimeSpan responseTime,
            double escalationRate)
        {
            if (completionRate < 0 || completionRate > 100)
                throw new BusinessException(
                    "PerformanceMetrics:InvalidCompletionRate",
                    "Completion rate must be between 0 and 100"
                );

            if (onTimeDelivery < 0 || onTimeDelivery > 100)
                throw new BusinessException(
                    "PerformanceMetrics:InvalidOnTimeDelivery",
                    "On-time delivery rate must be between 0 and 100"
                );

            if (qualityScore < 0 || qualityScore > 100)
                throw new BusinessException(
                    "PerformanceMetrics:InvalidQualityScore",
                    "Quality score must be between 0 and 100"
                );

            if (responseTime < TimeSpan.Zero)
                throw new BusinessException(
                    "PerformanceMetrics:InvalidResponseTime",
                    "Response time cannot be negative"
                );

            if (escalationRate < 0 || escalationRate > 100)
                throw new BusinessException(
                    "PerformanceMetrics:InvalidEscalationRate",
                    "Escalation rate must be between 0 and 100"
                );
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return CompletionRate;
            yield return OnTimeDelivery;
            yield return QualityScore;
            yield return ResponseTime;
            yield return EscalationRate;
        }

        public PerformanceRating CalculateOverallRating()
        {
            var weightedScore = 
                (CompletionRate * 0.3) +
                (OnTimeDelivery * 0.3) +
                (QualityScore * 0.25) +
                (Math.Max(0, 100 - EscalationRate) * 0.15);

            return weightedScore switch
            {
                >= 90 => PerformanceRating.Excellent,
                >= 80 => PerformanceRating.Good,
                >= 70 => PerformanceRating.Satisfactory,
                _ => PerformanceRating.NeedsImprovement
            };
        }
    }
}

