namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Services
{
    public class TaskAssignmentService : DomainService, ITaskAssignmentService
    {
        private readonly ILogger<TaskAssignmentService> _logger;
        private readonly IDelegatedTaskRepository _delegatedTaskRepository;
        private readonly IWorkloadRepository _workloadRepository;
        private readonly ISkillMatchRepository _skillMatchRepository;
        private readonly IDistributedEventBus _eventBus;

        public TaskAssignmentService(
            ILogger<TaskAssignmentService> logger,
            IDelegatedTaskRepository delegatedTaskRepository,
            IWorkloadRepository workloadRepository,
            ISkillMatchRepository skillMatchRepository,
            IDistributedEventBus eventBus)
        {
            _logger = logger;
            _delegatedTaskRepository = delegatedTaskRepository;
            _workloadRepository = workloadRepository;
            _skillMatchRepository = skillMatchRepository;
            _eventBus = eventBus;
        }

        public async Task<List<UserRef>> SuggestAssigneesAsync(
            Guid taskId,
            IEnumerable<SkillRequirement> requirements,
            CancellationToken cancellationToken = default)
        {
            try
            {
                _logger.LogInformation("Suggesting assignees for task {TaskId}", taskId);

                var skillMatchedUsers = await _skillMatchRepository.FindQualifiedUsersAsync(
                    requirements,
                    cancellationToken
                );

                var workloadOptimizedUsers = await _workloadRepository.GetUsersWithinWorkloadLimitsAsync(
                    skillMatchedUsers.Select(u => u.UserId),
                    cancellationToken
                );

                return workloadOptimizedUsers
                    .OrderByDescending(u => u.PerformanceRating)
                    .Take(5)
                    .ToList();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error suggesting assignees for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:SuggestAssignees",
                    "Failed to suggest assignees",
                    ex
                );
            }
        }

        public async Task<ValidationResult> ValidateAssignmentAsync(
            Guid taskId,
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var workloadResult = await _workloadRepository.CheckWorkloadLimitsAsync(
                    assigneeId,
                    cancellationToken
                );

                if (!workloadResult.IsWithinLimits)
                {
                    return ValidationResult.Fail(
                        "Workload",
                        "Assignee has exceeded workload limits"
                    );
                }

                var skillResult = await _skillMatchRepository.ValidateSkillRequirementsAsync(
                    taskId,
                    assigneeId,
                    cancellationToken
                );

                if (!skillResult.MeetsRequirements)
                {
                    return ValidationResult.Fail(
                        "Skills",
                        "Assignee does not meet skill requirements"
                    );
                }

                return ValidationResult.Success();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error validating assignment for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:ValidateAssignment",
                    "Failed to validate assignment",
                    ex
                );
            }
        }

        public async Task<WorkloadImpact> CalculateWorkloadImpactAsync(
            Guid taskId,
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var currentWorkload = await _workloadRepository.GetCurrentWorkloadAsync(
                    assigneeId,
                    cancellationToken
                );

                var taskEstimate = await _delegatedTaskRepository.GetTaskEstimateAsync(
                    taskId,
                    cancellationToken
                );

                return new WorkloadImpact(
                    currentWorkload.UtilizationRate + taskEstimate.EstimatedUtilization,
                    taskEstimate.Duration,
                    currentWorkload.AffectedProjectIds
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error calculating workload impact for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:CalculateWorkloadImpact",
                    "Failed to calculate workload impact",
                    ex
                );
            }
        }

        public async Task<SkillMatchResult> AssessSkillMatchAsync(
            Guid taskId,
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                return await _skillMatchRepository.AssessSkillMatchAsync(
                    taskId,
                    assigneeId,
                    cancellationToken
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error assessing skill match for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:AssessSkillMatch",
                    "Failed to assess skill match",
                    ex
                );
            }
        }

        public async Task<PerformanceReport> GeneratePerformanceReportAsync(
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var completedTasks = await _delegatedTaskRepository.GetCompletedTasksAsync(
                    assigneeId,
                    cancellationToken
                );

                return new PerformanceReport(
                    completedTasks.Select(t => t.PerformanceMetrics).ToList()
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error generating performance report for user {UserId}", assigneeId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:GeneratePerformanceReport",
                    "Failed to generate performance report",
                    ex
                );
            }
        }

        public async Task<EscalationResult> HandleEscalationsAsync(
            Guid taskId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var task = await _delegatedTaskRepository.GetAsync(
                    taskId,
                    cancellationToken
                );

                if (task == null)
                {
                    throw new TaskNotFoundException(taskId);
                }

                var escalationRules = task.EscalationRules
                    .Where(r => ShouldEscalate(task, r))
                    .ToList();

                foreach (var rule in escalationRules)
                {
                    await _eventBus.PublishAsync(
                        new TaskEscalatedEto
                        {
                            TaskId = taskId,
                            AssigneeUserId = task.Assignee.UserId,
                            EscalationReason = rule.Condition,
                            EscalationLevel = rule.EscalationLevel,
                            DelegationId = task.Id,
                            TenantId = task.TenantId
                        },
                        cancellationToken: cancellationToken
                    );
                }

                return new EscalationResult(
                    escalationRules.Count > 0,
                    escalationRules
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error handling escalations for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:HandleEscalations",
                    "Failed to handle escalations",
                    ex
                );
            }
        }

        private bool ShouldEscalate(DelegatedTaskAggregate task, EscalationRule rule)
        {
            return rule.Condition switch
            {
                EscalationCondition.Overdue => 
                    task.DueDate.HasValue && task.DueDate.Value < DateTimeOffset.UtcNow,
                EscalationCondition.Blocked => 
                    task.Status == DelegationStatus.Blocked,
                EscalationCondition.NoResponse => 
                    task.Status == DelegationStatus.PendingAcceptance && 
                    task.AcceptanceDeadline.HasValue && 
                    task.AcceptanceDeadline.Value < DateTimeOffset.UtcNow,
                EscalationCondition.PerformanceIssue => 
                    task.PerformanceMetrics?.CalculateOverallRating() == PerformanceRating.NeedsImprovement,
                _ => false
            };
        }
    }
}

