namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Specifications.Base
{
    public abstract class DelegatedTaskSpecificationBase : Specification<DelegatedTaskAggregate>
    {
        protected virtual bool IgnoreTenantFilter { get; } = false;
        protected virtual bool IgnoreDeletedFilter { get; } = false;

        protected override void ApplyFilter(FilterBuilder<DelegatedTaskAggregate> builder)
        {
            if (!IgnoreTenantFilter)
            {
                builder.And(e => e.TenantId == CurrentTenant.Id);
            }

            if (!IgnoreDeletedFilter)
            {
                builder.And(e => !e.IsDeleted);
            }
        }
    }
}

