        public TaskEscalatedEventHandler(
            ILogger<TaskEscalatedEventHandler> logger,
            IDelegatedTaskRepository delegatedTaskRepository)
        {
            _logger = logger;
            _delegatedTaskRepository = delegatedTaskRepository;
        }

        public async Task HandleEventAsync(TaskEscalatedEto eventData)
        {
            try
            {
                _logger.LogInformation(
                    "Processing escalation for task {TaskId} at level {Level}",
                    eventData.TaskId,
                    eventData.EscalationLevel
                );

                var task = await _delegatedTaskRepository.GetAsync(eventData.DelegationId);
                if (task == null)
                {
                    _logger.LogWarning(
                        "Task {TaskId} not found during escalation processing",
                        eventData.TaskId
                    );
                    return;
                }

                // Handle escalation based on reason
                switch (eventData.EscalationReason)
                {
                    case EscalationCondition.Overdue:
                        await HandleOverdueEscalationAsync(task, eventData.EscalationLevel);
                        break;
                    case EscalationCondition.NoResponse:
                        await HandleNoResponseEscalationAsync(task, eventData.EscalationLevel);
                        break;
                    case EscalationCondition.PerformanceIssue:
                        await HandlePerformanceEscalationAsync(task, eventData.EscalationLevel);
                        break;
                }

                await _delegatedTaskRepository.UpdateAsync(task);

                _logger.LogInformation(
                    "Successfully processed escalation for task {TaskId}",
                    eventData.TaskId
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(
                    ex,
                    "Error processing escalation for task {TaskId}",
                    eventData.TaskId
                );
                throw;
            }
        }

