    public class WorkloadManagementService : DomainService, IWorkloadManagementService
    {
        private readonly ILogger<WorkloadManagementService> _logger;
        private readonly IWorkloadRepository _workloadRepository;
        private readonly IDelegatedTaskRepository _delegatedTaskRepository;
        private readonly IDistributedEventBus _eventBus;

        public WorkloadManagementService(
            ILogger<WorkloadManagementService> logger,
            IWorkloadRepository workloadRepository,
            IDelegatedTaskRepository delegatedTaskRepository,
            IDistributedEventBus eventBus)
        {
            _logger = logger;
            _workloadRepository = workloadRepository;
            _delegatedTaskRepository = delegatedTaskRepository;
            _eventBus = eventBus;
        }

        public async Task<WorkloadDistribution> AnalyzeWorkloadDistributionAsync(
            Guid teamId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                _logger.LogInformation("Analyzing workload distribution for team {TeamId}", teamId);

                var teamWorkloads = await _workloadRepository.GetTeamWorkloadsAsync(
                    teamId,
                    cancellationToken
                );

                var distribution = new WorkloadDistribution(
                    teamWorkloads.Select(w => new UserWorkload(
                        w.UserId,
                        w.AssignedTasks,
                        w.UtilizationRate,
                        CalculateWorkloadBalance(w.UtilizationRate)
                    )).ToList()
                );

                if (distribution.HasImbalance())
                {
                    await _eventBus.PublishAsync(
                        new WorkloadImbalanceDetectedEto
                        {
                            TeamId = teamId,
                            ImbalanceMetrics = distribution.GetImbalanceMetrics(),
                            TenantId = CurrentTenant.Id
                        },
                        cancellationToken: cancellationToken
                    );
                }

                return distribution;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error analyzing workload distribution for team {TeamId}", teamId);
                throw new TaskDelegationDomainException(
                    "WorkloadManagement:AnalyzeDistribution",
                    "Failed to analyze workload distribution",
                    ex
                );
