        private RequirementsCriticality DetermineRequirementsCriticality(DelegatedTaskAggregate task)
        {
            return new RequirementsCriticality(
                task.Priority == DelegationPriority.Critical,
                task.SkillRequirements.Any(sr => sr.Priority == RequirementPriority.Must),
                task.DueDate.HasValue && (task.DueDate.Value - DateTimeOffset.UtcNow).TotalDays <= 7
            );
        }

        private List<SkillGapInfo> IdentifySkillGaps(
            List<UserSkill> userSkills,
            SkillRequirements requirements)
        {
            return requirements.RequiredSkills
                .Select(required =>
                {
                    var userSkill = userSkills.FirstOrDefault(us => us.SkillId == required.SkillId);
                    if (userSkill == null)
                    {
                        return new SkillGapInfo(
                            required.SkillId,
                            required.SkillName,
                            required.RequiredLevel,
                            ProficiencyLevel.Basic,
                            SkillGapSeverity.Missing
                        );
                    }

                    var severity = DetermineGapSeverity(
                        userSkill.CurrentLevel,
                        required.RequiredLevel
                    );

                    return new SkillGapInfo(
                        required.SkillId,
                        required.SkillName,
                        required.RequiredLevel,
                        userSkill.CurrentLevel,
                        severity
                    );
                })
                .Where(gap => gap.Severity != SkillGapSeverity.None)
                .ToList();
        }

        private List<SkillGapTrend> AnalyzeSkillGapTrends(
            List<UserSkill> userSkills,
            List<DelegatedTaskAggregate> recentTasks)
        {
            var skillFrequency = recentTasks
                .SelectMany(t => t.SkillRequirements)
                .GroupBy(sr => sr.SkillId)
                .ToDictionary(
                    g => g.Key,
                    g => g.Count()
                );

            return userSkills
                .Select(skill =>
                {
                    var frequency = skillFrequency.GetValueOrDefault(skill.SkillId, 0);
                    var trend = DetermineSkillTrend(frequency, skill.CurrentLevel);

                    return new SkillGapTrend(
                        skill.SkillId,
                        skill.SkillName,
                        skill.CurrentLevel,
                        frequency,
                        trend
                    );
                })
                .ToList();
        }

        private List<TrainingPriority> GenerateTrainingPriorities(
            List<UserSkill> userSkills,
            List<DelegatedTaskAggregate> recentTasks)
        {
            var gapTrends = AnalyzeSkillGapTrends(userSkills, recentTasks);

            return gapTrends
                .Select(trend =>
                {
                    var priority = CalculateTrainingPriority(trend);
                    var recommendations = GenerateTrainingRecommendations(trend);

                    return new TrainingPriority(
                        trend.SkillId,
                        trend.SkillName,
                        priority,
                        recommendations
                    );
                })
                .OrderByDescending(tp => tp.Priority)
                .ToList();
        }

        private SkillGapSeverity DetermineGapSeverity(
            ProficiencyLevel current,
            ProficiencyLevel required)
        {
            var gap = required - current;
            return gap switch
            {
                <= 0 => SkillGapSeverity.None,
                1 => SkillGapSeverity.Minor,
                2 => SkillGapSeverity.Moderate,
                _ => SkillGapSeverity.Severe
            };
        }

        private SkillTrend DetermineSkillTrend(int frequency, ProficiencyLevel currentLevel)
        {
            return (frequency, currentLevel) switch
            {
                ( > 10, _) => SkillTrend.HighDemand,
                ( > 5, ProficiencyLevel.Basic) => SkillTrend.NeedsImprovement,
                ( > 5, _) => SkillTrend.Stable,
                ( > 0, _) => SkillTrend.Occasional,
                _ => SkillTrend.Unused
            };
        }

        private TrainingPriorityLevel CalculateTrainingPriority(SkillGapTrend trend)
        {
            return (trend.Frequency, trend.Trend) switch
            {
                ( > 10, SkillTrend.HighDemand) => TrainingPriorityLevel.Critical,
                ( > 5, SkillTrend.NeedsImprovement) => TrainingPriorityLevel.High,
                ( > 5, _) => TrainingPriorityLevel.Medium,
                _ => TrainingPriorityLevel.Low
            };
        }

        private List<string> GenerateTrainingRecommendations(SkillGapTrend trend)
        {
            var recommendations = new List<string>();

            switch (trend.Trend)
            {
                case SkillTrend.HighDemand:
                    recommendations.Add("Consider formal training or certification");
                    recommendations.Add("Seek mentorship opportunities");
                    break;
                case SkillTrend.NeedsImprovement:
                    recommendations.Add("Focus on practical skill development");
                    recommendations.Add("Review online learning resources");
                    break;
                case SkillTrend.Stable:
                    recommendations.Add("Maintain current skill level");
                    recommendations.Add("Stay updated with latest developments");
                    break;
            }

            return recommendations;
        }
    }
}

