    public class EscalationRule : ValueObject
    {
        public Guid RuleId { get; private set; }
        public EscalationCondition Condition { get; private set; }
        public double ThresholdValue { get; private set; }
        public int EscalationLevel { get; private set; }
        private readonly List<UserRef> _notificationRecipients;
        public IReadOnlyCollection<UserRef> NotificationRecipients => _notificationRecipients.AsReadOnly();
        public TimeSpan GracePeriod { get; private set; }
        public bool IsActive { get; private set; }

        private EscalationRule()
        {
            _notificationRecipients = new List<UserRef>();
        }

        public EscalationRule(
            EscalationCondition condition,
            double thresholdValue,
            int escalationLevel,
            IEnumerable<UserRef> notificationRecipients,
            TimeSpan gracePeriod)
        {
            RuleId = Guid.NewGuid();
            Condition = condition;
            ThresholdValue = thresholdValue;
            EscalationLevel = escalationLevel;
            _notificationRecipients = notificationRecipients.ToList();
            GracePeriod = gracePeriod;
            IsActive = true;

            ValidateEscalationRule();
        }

        private void ValidateEscalationRule()
        {
            if (EscalationLevel < 1)
            {
                throw new BusinessException(
                    "EscalationRule:InvalidLevel",
                    "Escalation level must be greater than zero"
                );
            }

            if (ThresholdValue < 0)
            {
                throw new BusinessException(
                    "EscalationRule:InvalidThreshold",
                    "Threshold value cannot be negative"
                );
            }

            if (!_notificationRecipients.Any())
            {
                throw new BusinessException(
                    "EscalationRule:NoRecipients",
                    "At least one notification recipient is required"
                );
            }

            if (GracePeriod < TimeSpan.Zero)
            {
                throw new BusinessException(
                    "EscalationRule:InvalidGracePeriod",
                    "Grace period cannot be negative"
                );
            }
        }

        public void AddNotificationRecipient(UserRef recipient)
        {
            if (!_notificationRecipients.Contains(recipient))
            {
                _notificationRecipients.Add(recipient);
            }
        }

        public void RemoveNotificationRecipient(UserRef recipient)
        {
            _notificationRecipients.Remove(recipient);
            ValidateEscalationRule();
        }

        public void Deactivate()
        {
            IsActive = false;
        }

        public void Activate()
        {
            IsActive = true;
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return RuleId;
            yield return Condition;
            yield return ThresholdValue;
            yield return EscalationLevel;
            yield return GracePeriod;
            yield return IsActive;
            foreach (var recipient in _notificationRecipients)
            {
                yield return recipient;
            }
        }
    }
}

