        private double CalculateWorkloadBalance(IEnumerable<TeamWorkload> workloads)
        {
            var utilizationRates = workloads.Select(w => w.UtilizationRate).ToList();
            if (!utilizationRates.Any()) return 0;

            var average = utilizationRates.Average();
            var variance = utilizationRates.Sum(r => Math.Pow(r - average, 2)) / utilizationRates.Count;

            return 100 - Math.Sqrt(variance);
        }

