namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    public class UtilizationMetrics : ValueObject
    {
        public double CurrentUtilization { get; private set; }
        public double UtilizationThreshold { get; private set; }
        public UtilizationLevel UtilizationLevel { get; private set; }
        public IReadOnlyList<UtilizationTrend> HistoricalTrends { get; private set; }
        public TimeSpan AverageTaskDuration { get; private set; }
        public int ConcurrentTaskCount { get; private set; }

        private UtilizationMetrics() { }

        public UtilizationMetrics(
            CurrentWorkload currentWorkload,
            CapacityThresholds thresholds,
            UtilizationLevel level)
        {
            CurrentUtilization = currentWorkload.UtilizationRate;
            UtilizationThreshold = thresholds.OptimalThreshold;
            UtilizationLevel = level;
            ConcurrentTaskCount = currentWorkload.CurrentTasks;
            HistoricalTrends = currentWorkload.UtilizationHistory
                .Select(h => new UtilizationTrend(h.Timestamp, h.UtilizationRate))
                .ToList()
                .AsReadOnly();
            AverageTaskDuration = CalculateAverageTaskDuration(currentWorkload.TaskDurations);

            ValidateMetrics();
        }

        private void ValidateMetrics()
        {
            if (CurrentUtilization < 0 || CurrentUtilization > 100)
            {
                throw new BusinessException(
                    "UtilizationMetrics:InvalidUtilization",
                    "Utilization rate must be between 0 and 100"
                );
            }

            if (UtilizationThreshold <= 0 || UtilizationThreshold > 100)
            {
                throw new BusinessException(
                    "UtilizationMetrics:InvalidThreshold",
                    "Utilization threshold must be between 0 and 100"
                );
            }
        }

        private TimeSpan CalculateAverageTaskDuration(IEnumerable<TimeSpan> taskDurations)
        {
            var durations = taskDurations.ToList();
            if (!durations.Any()) return TimeSpan.Zero;

            var totalTicks = durations.Sum(d => d.Ticks);
            return TimeSpan.FromTicks(totalTicks / durations.Count);
        }

        public bool IsOverutilized()
        {
            return CurrentUtilization > UtilizationThreshold;
        }

        public bool HasCapacityFor(TimeSpan additionalWorkload)
        {
            var projectedUtilization = CurrentUtilization + 
                (additionalWorkload.TotalHours / AverageTaskDuration.TotalHours * 100);
            return projectedUtilization <= UtilizationThreshold;
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return CurrentUtilization;
            yield return UtilizationThreshold;
            yield return UtilizationLevel;
            yield return AverageTaskDuration;
            yield return ConcurrentTaskCount;
            foreach (var trend in HistoricalTrends)
            {
                yield return trend;
            }
        }
    }
}

