namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Shared.Policies
{
    public static class EscalationPolicies
    {
        public static class AutoEscalationPolicy
        {
            public static bool ShouldAutoEscalate(
                DelegatedTaskAggregate task,
                EscalationRule rule)
            {
                return rule.Condition switch
                {
                    EscalationCondition.Overdue => IsOverdue(task),
                    EscalationCondition.NoResponse => HasNoResponse(task),
                    EscalationCondition.PerformanceIssue => HasPerformanceIssue(task),
                    EscalationCondition.PendingAcceptance => IsPendingTooLong(task),
                    _ => false
                };
            }

            private static bool IsOverdue(DelegatedTaskAggregate task)
            {
                return task.DueDate.HasValue && 
                       task.DueDate.Value < DateTimeOffset.UtcNow &&
                       task.Status != DelegationStatus.Completed;
            }

            private static bool HasNoResponse(DelegatedTaskAggregate task)
            {
                return task.Status == DelegationStatus.PendingAcceptance &&
                       task.AcceptanceDeadline.HasValue &&
                       task.AcceptanceDeadline.Value < DateTimeOffset.UtcNow;
            }

            private static bool HasPerformanceIssue(DelegatedTaskAggregate task)
            {
                return task.PerformanceMetrics?.CalculateOverallRating() == 
                       PerformanceRating.NeedsImprovement;
            }

            private static bool IsPendingTooLong(DelegatedTaskAggregate task)
            {
                var pendingDuration = DateTimeOffset.UtcNow - task.AssignmentDate;
                return task.Status == DelegationStatus.PendingAcceptance &&
                       pendingDuration > TimeSpan.FromHours(24);
