namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Shared.Policies
{
    public static class WorkloadPolicies
    {
        public static class UtilizationPolicy
        {
            public static bool CanAcceptNewTask(
                WorkloadIndicator workload,
                TimeSpan estimatedTaskDuration)
            {
                if (workload.OverAllocationRisk == RiskLevel.High)
                {
                    return false;
                }

                var projectedUtilization = CalculateProjectedUtilization(
                    workload,
                    estimatedTaskDuration
                );

                return projectedUtilization <= WorkloadDistributionConsts.OptimalUtilizationTarget;
            }

            private static double CalculateProjectedUtilization(
                WorkloadIndicator workload,
                TimeSpan additionalWork)
            {
                var additionalUtilization = (additionalWork.TotalHours / 
                    workload.AvailableTime.TotalHours) * 100;
                return workload.UtilizationRate + additionalUtilization;
            }
        }

        public static class WorkloadBalancePolicy
        {
            public static bool IsBalanceAcceptable(WorkloadDistribution distribution)
            {
                return distribution.StandardDeviation <= 
                       WorkloadDistributionConsts.BalanceThreshold;
            }

            public static bool RequiresRebalancing(WorkloadDistribution distribution)
            {
                return distribution.StandardDeviation >= 
                       WorkloadDistributionConsts.CriticalImbalanceThreshold;
            }
        }
    }
}

