namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Shared.Policies
{
    /// <summary>
    /// Contains policies for task assignment constraints.
    /// </summary>
    public static class AssignmentConstraintPolicies
    {
        public static class TimeZonePolicy
        {
            public static bool IsTimeZoneCompatible(
                TimeZoneRestriction restriction,
                TimeSpan assigneeOffset)
            {
                return restriction.IsCompatibleWith(assigneeOffset);
            }
        }

        public static class WorkingHoursPolicy
        {
            public static bool HasSufficientOverlap(
                IEnumerable<WorkingHours> taskHours,
                IEnumerable<WorkingHours> assigneeHours)
            {
                var taskWorkingHours = taskHours.Where(h => h.IsWorkingDay)
                    .ToDictionary(h => h.DayOfWeek);
                var assigneeWorkingHours = assigneeHours.Where(h => h.IsWorkingDay)
                    .ToDictionary(h => h.DayOfWeek);

                var commonWorkingDays = taskWorkingHours.Keys
                    .Intersect(assigneeWorkingHours.Keys);

                if (!commonWorkingDays.Any())
                {
                    return false;
                }

                foreach (var day in commonWorkingDays)
                {
                    var taskHrs = taskWorkingHours[day];
                    var assigneeHrs = assigneeWorkingHours[day];

                    var overlapStart = taskHrs.StartTime > assigneeHrs.StartTime 
                        ? taskHrs.StartTime 
                        : assigneeHrs.StartTime;

                    var overlapEnd = taskHrs.EndTime < assigneeHrs.EndTime 
                        ? taskHrs.EndTime 
                        : assigneeHrs.EndTime;

                    if (overlapEnd <= overlapStart)
                    {
                        return false;
                    }

                    var overlapDuration = overlapEnd - overlapStart;
                    if (overlapDuration < TimeSpan.FromHours(4))
                    {
                        return false;
                    }
                }

                return true;
            }
        }

        public static class SkillMatchPolicy
        {
            public static bool MeetsSkillRequirements(
                IEnumerable<SkillRequirement> required,
                IEnumerable<UserSkill> available)
            {
                var requiredSkills = required.ToList();
                var availableSkills = available.ToDictionary(s => s.SkillId);

                foreach (var requirement in requiredSkills)
                {
                    if (requirement.Priority == RequirementPriority.Must)
                    {
                        if (!availableSkills.ContainsKey(requirement.SkillId))
                        {
                            return false;
                        }

                        var userSkill = availableSkills[requirement.SkillId];
                        if (userSkill.CurrentLevel < requirement.RequiredLevel)
                        {
                            return false;
                        }
                    }
                }

                var matchedShouldSkills = requiredSkills
                    .Where(r => r.Priority == RequirementPriority.Should)
                    .Count(r => availableSkills.ContainsKey(r.SkillId) && 
                               availableSkills[r.SkillId].CurrentLevel >= r.RequiredLevel);

                return matchedShouldSkills >= requiredSkills
                    .Count(r => r.Priority == RequirementPriority.Should) * 0.7;
            }
        }

        public static class WorkloadBalancePolicy
        {
            public static bool IsAssignmentBalanced(
                WorkloadDistribution distribution,
                UserRef proposedAssignee)
            {
                var assigneeWorkload = distribution.TeamWorkloads
                    .FirstOrDefault(w => w.UserId == proposedAssignee.UserId);

                if (assigneeWorkload == null)
                {
                    return true;
                }

                return assigneeWorkload.UtilizationRate <= 
                       distribution.AverageUtilization + distribution.StandardDeviation;
            }
        }
    }
}

