namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Shared.Policies
{
    /// <summary>
    /// Contains policies for performance thresholds.
    /// </summary>
    public static class PerformanceThresholdPolicies
    {
        public static class CompletionRatePolicy
        {
            public const double MinimumAcceptableCompletionRate = 80.0;
            public const double OptimalCompletionRate = 95.0;

            public static bool MeetsCompletionThreshold(PerformanceMetrics metrics)
            {
                return metrics.CompletionRate >= MinimumAcceptableCompletionRate;
            }

            public static bool IsHighPerformer(PerformanceMetrics metrics)
            {
                return metrics.CompletionRate >= OptimalCompletionRate;
            }
        }

        public static class QualityPolicy
        {
            public const double MinimumQualityScore = 75.0;
            public const double HighQualityThreshold = 90.0;

            public static bool MeetsQualityStandards(PerformanceMetrics metrics)
            {
                return metrics.QualityScore >= MinimumQualityScore;
            }

            public static bool IsHighQualityPerformer(PerformanceMetrics metrics)
            {
                return metrics.QualityScore >= HighQualityThreshold;
            }
        }

        public static class ResponseTimePolicy
        {
            public static readonly TimeSpan MaxAcceptableResponseTime = TimeSpan.FromHours(24);
            public static readonly TimeSpan OptimalResponseTime = TimeSpan.FromHours(4);

            public static bool HasAcceptableResponseTime(PerformanceMetrics metrics)
            {
                return metrics.ResponseTime <= MaxAcceptableResponseTime;
            }

            public static bool HasOptimalResponseTime(PerformanceMetrics metrics)
            {
                return metrics.ResponseTime <= OptimalResponseTime;
            }
        }

        public static class EscalationRatePolicy
        {
            public const double MaxAcceptableEscalationRate = 20.0;
            public const double CriticalEscalationThreshold = 30.0;

            public static bool HasAcceptableEscalationRate(PerformanceMetrics metrics)
            {
                return metrics.EscalationRate <= MaxAcceptableEscalationRate;
            }

            public static bool RequiresIntervention(PerformanceMetrics metrics)
            {
                return metrics.EscalationRate >= CriticalEscalationThreshold;
            }
        }

        public static class OverallPerformancePolicy
        {
            public static bool IsEligibleForCriticalTasks(PerformanceMetrics metrics)
            {
                return CompletionRatePolicy.IsHighPerformer(metrics) &&
                       QualityPolicy.IsHighQualityPerformer(metrics) &&
                       ResponseTimePolicy.HasOptimalResponseTime(metrics) &&
                       EscalationRatePolicy.HasAcceptableEscalationRate(metrics);
            }

            public static bool RequiresPerformanceImprovement(PerformanceMetrics metrics)
            {
                var failedCriteria = 0;

                if (!CompletionRatePolicy.MeetsCompletionThreshold(metrics)) failedCriteria++;
                if (!QualityPolicy.MeetsQualityStandards(metrics)) failedCriteria++;
                if (!ResponseTimePolicy.HasAcceptableResponseTime(metrics)) failedCriteria++;
                if (!EscalationRatePolicy.HasAcceptableEscalationRate(metrics)) failedCriteria++;

                return failedCriteria >= 2;
            }

            public static PerformanceImprovementPriority GetImprovementPriority(PerformanceMetrics metrics)
            {
                if (RequiresPerformanceImprovement(metrics))
                {
                    if (EscalationRatePolicy.RequiresIntervention(metrics))
                    {
                        return PerformanceImprovementPriority.Critical;
                    }
                    return PerformanceImprovementPriority.High;
                }

                if (!IsEligibleForCriticalTasks(metrics))
                {
                    return PerformanceImprovementPriority.Medium;
                }

                return PerformanceImprovementPriority.Low;
            }
        }
    }
}
