namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Value object that represents working hours for a day.
    /// </summary>
    public class WorkingHours : ValueObject
    {
        public DayOfWeek DayOfWeek { get; private set; }
        public TimeSpan StartTime { get; private set; }
        public TimeSpan EndTime { get; private set; }
        public bool IsWorkingDay { get; private set; }
        public List<TimeSpan> BreakPeriods { get; private set; }

        private WorkingHours() 
        {
            BreakPeriods = new List<TimeSpan>();
        }

        public WorkingHours(
            DayOfWeek dayOfWeek,
            TimeSpan startTime,
            TimeSpan endTime,
            bool isWorkingDay,
            List<TimeSpan> breakPeriods)
        {
            DayOfWeek = dayOfWeek;
            IsWorkingDay = isWorkingDay;
            BreakPeriods = breakPeriods ?? new List<TimeSpan>();

            if (isWorkingDay)
            {
                ValidateWorkingHours(startTime, endTime);
                StartTime = startTime;
                EndTime = endTime;
            }
        }

        private void ValidateWorkingHours(TimeSpan startTime, TimeSpan endTime)
        {
            if (startTime >= endTime)
            {
                throw new BusinessException(
                    "WorkingHours:InvalidTimeRange",
                    "Start time must be before end time"
                );
            }

            if (startTime.TotalHours < 0 || startTime.TotalHours > 24 ||
                endTime.TotalHours < 0 || endTime.TotalHours > 24)
            {
                throw new BusinessException(
                    "WorkingHours:InvalidTime",
                    "Time values must be between 0 and 24 hours"
                );
            }
        }

        public TimeSpan CalculateWorkingHours()
        {
            if (!IsWorkingDay) return TimeSpan.Zero;

            var totalWorkTime = EndTime - StartTime;
            var totalBreakTime = BreakPeriods.Aggregate(
                TimeSpan.Zero,
                (current, breakPeriod) => current + breakPeriod
            );

            return totalWorkTime - totalBreakTime;
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return DayOfWeek;
            yield return StartTime;
            yield return EndTime;
            yield return IsWorkingDay;
            foreach (var breakPeriod in BreakPeriods)
            {
                yield return breakPeriod;
            }
        }
    }
}

