namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Value object that represents the impact of a task on workload.
    /// </summary>
    public class WorkloadImpact : ValueObject
    {
        public double ExpectedUtilizationIncrease { get; private set; }
        public RiskLevel RiskLevel { get; private set; }
        public TimeSpan ImpactDuration { get; private set; }
        public IReadOnlyList<Guid> AffectedProjects { get; private set; }
        public double CurrentUtilization { get; private set; }
        public double ProjectedUtilization => CurrentUtilization + ExpectedUtilizationIncrease;

        private WorkloadImpact() { }

        public WorkloadImpact(
            double expectedUtilizationIncrease,
            TimeSpan impactDuration,
            IEnumerable<Guid> affectedProjects,
            double currentUtilization = 0)
        {
            ExpectedUtilizationIncrease = expectedUtilizationIncrease;
            ImpactDuration = impactDuration;
            AffectedProjects = affectedProjects.ToList().AsReadOnly();
            CurrentUtilization = currentUtilization;

            ValidateWorkloadImpact();
            CalculateRiskLevel();
        }

        private void ValidateWorkloadImpact()
        {
            if (ExpectedUtilizationIncrease < 0)
            {
                throw new BusinessException(
                    "WorkloadImpact:InvalidUtilization",
                    "Expected utilization increase cannot be negative"
                );
            }

            if (ImpactDuration < TimeSpan.Zero)
            {
                throw new BusinessException(
                    "WorkloadImpact:InvalidDuration",
                    "Impact duration cannot be negative"
                );
            }
        }

        private void CalculateRiskLevel()
        {
            RiskLevel = ProjectedUtilization switch
            {
                <= 70 => RiskLevel.Low,
                <= 85 => RiskLevel.Medium,
                _ => RiskLevel.High
            };
        }

        public bool IsAcceptable()
        {
            return RiskLevel != RiskLevel.High && ProjectedUtilization <= 100;
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return ExpectedUtilizationIncrease;
            yield return RiskLevel;
            yield return ImpactDuration;
            foreach (var projectId in AffectedProjects)
            {
                yield return projectId;
            }
            yield return CurrentUtilization;
        }
    }
}

