    public class UserSkill : ValueObject
    {
        public Guid SkillId { get; private set; }
        public string SkillName { get; private set; }
        public ProficiencyLevel CurrentLevel { get; private set; }
        public DateTimeOffset LastUsedDate { get; private set; }
        public int ExperiencePoints { get; private set; }

        private UserSkill() { }

        public UserSkill(
            Guid skillId,
            string skillName,
            ProficiencyLevel currentLevel)
        {
            SkillId = skillId;
            SkillName = Check.NotNullOrWhiteSpace(
                skillName,
                nameof(skillName),
                maxLength: SkillRequirementConsts.MaxSkillNameLength
            );
