        {
            return level switch
            {
                ProficiencyLevel.Basic => 100,
                ProficiencyLevel.Intermediate => 300,
                ProficiencyLevel.Advanced => 600,
                ProficiencyLevel.Expert => 1000,
                _ => 0
            };
        }

