        {
            LastUsedDate = DateTimeOffset.UtcNow;
        }

        private void UpdateProficiencyLevel()
        {
            CurrentLevel = ExperiencePoints switch
            {
                < 250 => ProficiencyLevel.Basic,
                < 500 => ProficiencyLevel.Intermediate,
                < 800 => ProficiencyLevel.Advanced,
                _ => ProficiencyLevel.Expert
            };
        }

