namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Value object that represents an optimization of task assignments.
    /// </summary>
    public class AssignmentOptimization : ValueObject
    {
        public IReadOnlyList<CurrentAssignment> CurrentAssignments { get; private set; }
        public IReadOnlyList<TeamWorkload> TeamWorkloads { get; private set; }
        public IReadOnlyList<AssignmentRecommendation> Recommendations { get; private set; }
        public double CurrentBalanceScore { get; private set; }
        public double OptimizedBalanceScore { get; private set; }
        public double ImprovementPercentage => 
            ((OptimizedBalanceScore - CurrentBalanceScore) / CurrentBalanceScore) * 100;

        private AssignmentOptimization() { }

        public AssignmentOptimization(
            IEnumerable<CurrentAssignment> currentAssignments,
            IEnumerable<TeamWorkload> teamWorkloads,
            IEnumerable<AssignmentRecommendation> recommendations)
        {
            CurrentAssignments = currentAssignments.ToList().AsReadOnly();
            TeamWorkloads = teamWorkloads.ToList().AsReadOnly();
            Recommendations = recommendations.ToList().AsReadOnly();

            CalculateBalanceScores();
        }

        private void CalculateBalanceScores()
        {
            CurrentBalanceScore = CalculateWorkloadBalance(TeamWorkloads);
            OptimizedBalanceScore = SimulateOptimizedBalance(Recommendations);
        }

        private double CalculateWorkloadBalance(IEnumerable<TeamWorkload> workloads)
        {
            var utilizationRates = workloads.Select(w => w.UtilizationRate).ToList();
            if (!utilizationRates.Any()) return 0;

            var average = utilizationRates.Average();
            var variance = utilizationRates.Sum(r => Math.Pow(r - average, 2)) / utilizationRates.Count;

            return 100 - Math.Sqrt(variance);
        }

        private double SimulateOptimizedBalance(IEnumerable<AssignmentRecommendation> recommendations)
        {
            var simulatedWorkloads = TeamWorkloads.Select(w => new TeamWorkload
            {
                UserId = w.UserId,
                AssignedTasks = w.AssignedTasks,
                UtilizationRate = w.UtilizationRate
            }).ToList();

            foreach (var recommendation in recommendations)
            {
                ApplyRecommendation(simulatedWorkloads, recommendation);
            }

            return CalculateWorkloadBalance(simulatedWorkloads);
        }

        private void ApplyRecommendation(
            List<TeamWorkload> workloads,
            AssignmentRecommendation recommendation)
        {
            var currentAssignee = workloads.FirstOrDefault(w => w.UserId == recommendation.CurrentAssigneeId);
            var newAssignee = workloads.FirstOrDefault(w => w.UserId == recommendation.RecommendedAssigneeId);

            if (currentAssignee != null && newAssignee != null)
            {
                currentAssignee.UtilizationRate -= recommendation.TaskUtilization;
                currentAssignee.AssignedTasks--;

                newAssignee.UtilizationRate += recommendation.TaskUtilization;
                newAssignee.AssignedTasks++;
            }
        }

        public bool HasSignificantImprovements()
        {
            return ImprovementPercentage >= 10;
        }

        public OptimizationMetrics GetImprovementMetrics()
        {
            return new OptimizationMetrics
            {
                CurrentBalance = CurrentBalanceScore,
                OptimizedBalance = OptimizedBalanceScore,
                ImprovementPercentage = ImprovementPercentage,
