namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Value object that represents workload distribution across a team.
    /// </summary>
    public class WorkloadDistribution : ValueObject
    {
        public IReadOnlyCollection<UserWorkload> TeamWorkloads { get; private set; }
        public double AverageUtilization { get; private set; }
        public double UtilizationVariance { get; private set; }
        public double StandardDeviation { get; private set; }
        public bool IsBalanced => StandardDeviation <= WorkloadDistributionConsts.BalanceThreshold;

        private WorkloadDistribution() { }

        public WorkloadDistribution(IEnumerable<UserWorkload> teamWorkloads)
        {
            TeamWorkloads = teamWorkloads.ToList().AsReadOnly();
            CalculateDistributionMetrics();
        }

        private void CalculateDistributionMetrics()
        {
            if (!TeamWorkloads.Any())
            {
                AverageUtilization = 0;
                UtilizationVariance = 0;
                StandardDeviation = 0;
                return;
            }

            AverageUtilization = TeamWorkloads.Average(w => w.UtilizationRate);
            UtilizationVariance = TeamWorkloads.Sum(w => 
                Math.Pow(w.UtilizationRate - AverageUtilization, 2)) / TeamWorkloads.Count;
            StandardDeviation = Math.Sqrt(UtilizationVariance);
        }

        public bool HasImbalance()
        {
            return StandardDeviation > WorkloadDistributionConsts.BalanceThreshold;
        }

        public ImbalanceMetrics GetImbalanceMetrics()
        {
            var overutilized = TeamWorkloads.Count(w => 
                w.UtilizationRate > AverageUtilization + StandardDeviation);
            var underutilized = TeamWorkloads.Count(w => 
                w.UtilizationRate < AverageUtilization - StandardDeviation);

            return new ImbalanceMetrics
            {
                ImbalanceSeverity = StandardDeviation,
                OverutilizedCount = overutilized,
                UnderutilizedCount = underutilized,
                TotalTeamMembers = TeamWorkloads.Count
            };
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            foreach (var workload in TeamWorkloads) yield return workload;
            yield return AverageUtilization;
            yield return UtilizationVariance;
            yield return StandardDeviation;
        }
    }
}
