    public class SkillMatch : ValueObject
    {
        public SkillRequirement Requirement { get; private set; }
        public bool HasSkill { get; private set; }
        public ProficiencyLevel ActualLevel { get; private set; }
        public bool IsMatch => HasSkill && ActualLevel >= Requirement.RequiredLevel;
        public double MatchPercentage { get; private set; }

        private SkillMatch() { }

        public SkillMatch(
            SkillRequirement requirement,
            bool hasSkill,
            ProficiencyLevel actualLevel)
        {
            Requirement = requirement;
            HasSkill = hasSkill;
            ActualLevel = actualLevel;

            CalculateMatchPercentage();
        }

        private void CalculateMatchPercentage()
        {
            if (!HasSkill) 
            {
                MatchPercentage = 0;
                return;
            }

            var requiredLevel = (int)Requirement.RequiredLevel;
            var userLevel = (int)ActualLevel;

            if (userLevel >= requiredLevel)
            {
                MatchPercentage = 100;
            }
            else
            {
                MatchPercentage = (userLevel * 100.0) / requiredLevel;
            }
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return Requirement;
            yield return HasSkill;
            yield return ActualLevel;
            yield return MatchPercentage;
        }
    }
