    public class TaskEstimate : ValueObject
    {
        public Guid TaskId { get; private set; }
        public TimeSpan Duration { get; private set; }
        public double EstimatedUtilization { get; private set; }
        public Guid? ProjectId { get; private set; }
        public DelegationPriority Priority { get; private set; }

