            Guid taskId,
            TimeSpan duration,
            double estimatedUtilization,
            Guid? projectId,
            DelegationPriority priority)
        {
            TaskId = taskId;
            Duration = duration;
            EstimatedUtilization = estimatedUtilization;
            ProjectId = projectId;
            Priority = priority;

            ValidateEstimate();
        }

