// File: NouAssist.Productivity.TaskProjectGTD.TaskDelegation/Domain/Aggregates/DelegatedTaskAggregate.cs (continued)
        public string Notes { get; private set; }
        public DelegationReason DelegationReason { get; private set; }
        public WorkloadIndicator WorkloadIndicator { get; private set; }
        public PerformanceMetrics PerformanceMetrics { get; private set; }
        public DelegationPriority Priority { get; private set; }
        public CompetencyLevel CompetencyLevel { get; private set; }
        public DateTimeOffset? AcceptanceDeadline { get; private set; }
        public WorkloadImpact WorkloadImpact { get; private set; }
        public int Version { get; private set; }

        private readonly List<SkillRequirement> _skillRequirements;
        public IReadOnlyCollection<SkillRequirement> SkillRequirements => _skillRequirements.AsReadOnly();

        private readonly List<DelegationHistoryEntry> _delegationHistory;
        public IReadOnlyCollection<DelegationHistoryEntry> DelegationHistory => _delegationHistory.AsReadOnly();

        private readonly List<EscalationRule> _escalationRules;
        public IReadOnlyCollection<EscalationRule> EscalationRules => _escalationRules.AsReadOnly();

        protected DelegatedTaskAggregate()
        {
            _skillRequirements = new List<SkillRequirement>();
            _delegationHistory = new List<DelegationHistoryEntry>();
            _escalationRules = new List<EscalationRule>();
        }

        internal DelegatedTaskAggregate(
            Guid id,
            Guid taskId,
            UserRef assignee,
            UserRef delegator,
            DateTimeOffset? dueDate,
            string notes,
            DelegationReason reason,
            DelegationPriority priority,
            CompetencyLevel competencyLevel,
            Guid? tenantId) : base(id)
        {
            TenantId = tenantId;
            TaskId = taskId;
            AssignmentDate = DateTimeOffset.UtcNow;
            Status = DelegationStatus.PendingAcceptance;
            Version = 1;
            _skillRequirements = new List<SkillRequirement>();
            _delegationHistory = new List<DelegationHistoryEntry>();
            _escalationRules = new List<EscalationRule>();

            SetAssignee(assignee);
            SetDelegator(delegator);
            SetDueDate(dueDate);
            SetNotes(notes);
            SetDelegationReason(reason);
            SetPriority(priority);
            SetCompetencyLevel(competencyLevel);

            AddHistoryEntry(DelegationAction.Assigned, null, assignee, "Initial assignment");

            AddDomainEvent(new TaskAssignedEto
            {
                TaskId = TaskId,
                AssigneeUserId = assignee.UserId,
                DelegatorUserId = delegator.UserId,
                DueDate = dueDate,
                DelegationReason = reason,
                TenantId = TenantId
            });
        }

        public void AcceptDelegation(Guid acceptorUserId)
        {
            if (Status != DelegationStatus.PendingAcceptance)
                throw new TaskDelegationDomainException("TaskDelegation:InvalidAcceptance", "Task is not in pending acceptance status.");

            if (acceptorUserId != Assignee.UserId)
                throw new TaskDelegationDomainException("TaskDelegation:UnauthorizedAcceptance", "Only the assigned user can accept the delegation.");

            Status = DelegationStatus.Accepted;
            IncrementVersion();
            AddHistoryEntry(DelegationAction.Accepted, Assignee, Assignee, "Delegation accepted by assignee");

            AddDomainEvent(new DelegationAcceptedEto
            {
                TaskId = TaskId,
                AssigneeUserId = acceptorUserId,
                DelegationId = Id,
                TenantId = TenantId
            });
        }

        public void DeclineDelegation(Guid declinerUserId, string reason)
        {
            if (Status != DelegationStatus.PendingAcceptance)
                throw new TaskDelegationDomainException("TaskDelegation:InvalidDecline", "Task is not in pending acceptance status.");

            if (declinerUserId != Assignee.UserId)
                throw new TaskDelegationDomainException("TaskDelegation:UnauthorizedDecline", "Only the assigned user can decline the delegation.");

            Status = DelegationStatus.Declined;
            IncrementVersion();
            AddHistoryEntry(DelegationAction.Declined, Assignee, null, reason);

            AddDomainEvent(new DelegationDeclinedEto
            {
                TaskId = TaskId,
                AssigneeUserId = declinerUserId,
                DelegationId = Id,
                DeclineReason = reason,
                TenantId = TenantId
            });
        }

        public void UpdateStatus(DelegationStatus newStatus)
        {
            var oldStatus = Status;
            ValidateStatusTransition(newStatus);
            Status = newStatus;
            IncrementVersion();

            AddHistoryEntry(
                DelegationAction.StatusChanged,
                Assignee,
                Assignee,
                $"Status changed from {oldStatus} to {newStatus}"
            );

            AddDomainEvent(new TaskDelegationStatusChangedEto
            {
                TaskId = TaskId,
                AssigneeUserId = Assignee.UserId,
                OldStatus = oldStatus,
                NewStatus = newStatus,
                DelegationId = Id,
                TenantId = TenantId
            });
        }

        public void ReassignTask(UserRef newAssignee, string notes, DelegationReason reason)
        {
            if (Status == DelegationStatus.Completed)
                throw new TaskDelegationDomainException("TaskDelegation:InvalidReassignment", "Cannot reassign completed tasks.");

            var previousAssignee = Assignee;
            SetAssignee(newAssignee);
            SetNotes(notes);
            SetDelegationReason(reason);
            Status = DelegationStatus.PendingAcceptance;
            IncrementVersion();

            AddHistoryEntry(DelegationAction.Reassigned, previousAssignee, newAssignee, notes);

            AddDomainEvent(new TaskReassignedEto
            {
                TaskId = TaskId,
                OldAssigneeUserId = previousAssignee.UserId,
                NewAssigneeUserId = newAssignee.UserId,
                DelegationReason = reason,
                DelegationId = Id,
                TenantId = TenantId
            });
        }

        public void AddNote(string note)
        {
            if (string.IsNullOrWhiteSpace(note))
                throw new ArgumentException("Note cannot be empty", nameof(note));

            Notes = string.IsNullOrWhiteSpace(Notes) 
                ? note 
                : $"{Notes}\n{note}";

            IncrementVersion();
        }

        public void UpdatePerformanceMetrics(PerformanceMetrics metrics)
        {
            PerformanceMetrics = metrics;
            IncrementVersion();

            AddDomainEvent(new PerformanceMetricsUpdatedEto
            {
                TaskId = TaskId,
                AssigneeUserId = Assignee.UserId,
                Metrics = metrics,
                DelegationId = Id,
                TenantId = TenantId
            });
        }

        public void UpdateWorkloadIndicator(WorkloadIndicator workload)
        {
            WorkloadIndicator = workload;
            IncrementVersion();

            if (workload.OverAllocationRisk == RiskLevel.High)
            {
                AddDomainEvent(new WorkloadThresholdExceededEto
                {
                    UserId = Assignee.UserId,
                    CurrentWorkload = workload.UtilizationRate,
                    TenantId = TenantId
                });
            }
        }

        public void UpdateWorkloadImpact(WorkloadImpact impact)
        {
            WorkloadImpact = impact;
            IncrementVersion();

            AddDomainEvent(new WorkloadImpactAssessedEto
            {
                TaskId = TaskId,
                Impact = impact,
                TenantId = TenantId
            });
        }

        public void SetAcceptanceDeadline(DateTimeOffset deadline)
        {
            if (deadline <= DateTimeOffset.UtcNow)
                throw new TaskDelegationDomainException("TaskDelegation:InvalidDeadline", "Acceptance deadline must be in the future.");

            AcceptanceDeadline = deadline;
            IncrementVersion();
        }

        public void AddSkillRequirement(SkillRequirement requirement)
        {
            if (_skillRequirements.Any(s => s.SkillId == requirement.SkillId))
            {
                throw new TaskDelegationDomainException(
                    "TaskDelegation:DuplicateSkill", 
                    $"Skill '{requirement.SkillName}' is already required."
                );
            }

            _skillRequirements.Add(requirement);
            IncrementVersion();
        }

        public void RemoveSkillRequirement(Guid skillId)
        {
            var requirement = _skillRequirements.FirstOrDefault(s => s.SkillId == skillId);
            if (requirement != null)
            {
                _skillRequirements.Remove(requirement);
                IncrementVersion();
            }
        }

        public void AddEscalationRule(EscalationRule rule)
        {
            _escalationRules.Add(rule);
            IncrementVersion();
        }

        public void RemoveEscalationRule(Guid ruleId)
        {
            var rule = _escalationRules.FirstOrDefault(r => r.RuleId == ruleId);
            if (rule != null)
            {
                _escalationRules.Remove(rule);
                IncrementVersion();
            }
        }

        private void ValidateStatusTransition(DelegationStatus newStatus)
        {
            var isValid = Status switch
            {
                DelegationStatus.PendingAcceptance => 
                    newStatus is DelegationStatus.Accepted or DelegationStatus.Declined,
                DelegationStatus.Accepted => 
                    newStatus is DelegationStatus.InProgress or DelegationStatus.Blocked,
                DelegationStatus.InProgress => 
                    newStatus is DelegationStatus.Completed or DelegationStatus.Blocked,
                DelegationStatus.Blocked => 
                    newStatus is DelegationStatus.InProgress,
                _ => false
            };

            if (!isValid)
                throw new TaskDelegationDomainException(
                    "TaskDelegation:InvalidStatusTransition",
                    $"Cannot transition from {Status} to {newStatus}"
                );
        }

        private void SetAssignee(UserRef assignee)
        {
            Assignee = assignee ?? throw new ArgumentNullException(nameof(assignee));
        }

        private void SetDelegator(UserRef delegator)
        {
            Delegator = delegator ?? throw new ArgumentNullException(nameof(delegator));
        }

        private void SetDueDate(DateTimeOffset? dueDate)
        {
            if (dueDate.HasValue && dueDate.Value < DateTimeOffset.UtcNow)
                throw new TaskDelegationDomainException("TaskDelegation:InvalidDueDate", "Due date cannot be in the past.");

            DueDate = dueDate;
        }

        private void SetNotes(string notes)
        {
            Notes = Check.NotNullOrWhiteSpace(notes, nameof(notes), DelegatedTaskConsts.MaxNotesLength);
        }

        private void SetDelegationReason(DelegationReason reason)
        {
            DelegationReason = reason;
        }

        private void SetPriority(DelegationPriority priority)
        {
            Priority = priority;
        }

        private void SetCompetencyLevel(CompetencyLevel level)
        {
            CompetencyLevel = level;
        }

        private void AddHistoryEntry(
            DelegationAction action,
            UserRef? previousAssignee,
            UserRef? newAssignee,
            string reason)
        {
            _delegationHistory.Add(new DelegationHistoryEntry(
                action,
                previousAssignee,
                newAssignee,
                reason
            ));
        }

        private void IncrementVersion()
        {
            Version++;
        }
    }
}

