    public class SkillValidationResult : ValueObject
    {
        public Guid UserId { get; private set; }
        public bool MeetsRequirements { get; private set; }
        public List<string> MissingSkills { get; private set; }
        public List<string> InsufficientSkills { get; private set; }

        private SkillValidationResult() 
        {
            MissingSkills = new List<string>();
            InsufficientSkills = new List<string>();
        }

        public SkillValidationResult(
            Guid userId,
            bool meetsRequirements,
            IEnumerable<string> missingSkills,
            IEnumerable<string> insufficientSkills)
        {
            UserId = userId;
            MeetsRequirements = meetsRequirements;
            MissingSkills = missingSkills.ToList();
            InsufficientSkills = insufficientSkills.ToList();
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return UserId;
            yield return MeetsRequirements;
            foreach (var skill in MissingSkills)
            {
                yield return skill;
            }
            foreach (var skill in InsufficientSkills)
            {
                yield return skill;
            }
        }
    }
}

