namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Services
{
    /// <summary>
    /// Domain service for task assignment operations.
    /// </summary>
    public class TaskAssignmentService : DomainService, ITaskAssignmentService
    {
        private readonly ILogger<TaskAssignmentService> _logger;
        private readonly IDelegatedTaskRepository _delegatedTaskRepository;
        private readonly IWorkloadRepository _workloadRepository;
        private readonly ISkillMatchRepository _skillMatchRepository;
        private readonly IDistributedEventBus _eventBus;

        public TaskAssignmentService(
            ILogger<TaskAssignmentService> logger,
            IDelegatedTaskRepository delegatedTaskRepository,
            IWorkloadRepository workloadRepository,
            ISkillMatchRepository skillMatchRepository,
            IDistributedEventBus eventBus)
        {
            _logger = logger;
            _delegatedTaskRepository = delegatedTaskRepository;
            _workloadRepository = workloadRepository;
            _skillMatchRepository = skillMatchRepository;
            _eventBus = eventBus;
        }

        public async Task<List<UserRef>> SuggestAssigneesAsync(
            Guid taskId,
            IEnumerable<SkillRequirement> requirements,
            CancellationToken cancellationToken = default)
        {
            try
            {
                _logger.LogInformation("Suggesting assignees for task {TaskId}", taskId);

                var skillMatchedUsers = await _skillMatchRepository.FindQualifiedUsersAsync(
                    requirements,
                    cancellationToken
                );

                var workloadOptimizedUsers = await _workloadRepository.GetUsersWithinWorkloadLimitsAsync(
                    skillMatchedUsers.Select(u => u.UserId),
                    cancellationToken
                );

                return workloadOptimizedUsers
                    .OrderByDescending(u => u.DisplayName)
                    .Take(5)
                    .ToList();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error suggesting assignees for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:SuggestAssignees",
                    "Failed to suggest assignees",
                    ex
                );
            }
        }

        public async Task<ValidationResult> ValidateAssignmentAsync(
            Guid taskId,
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var workloadResult = await _workloadRepository.CheckWorkloadLimitsAsync(
                    assigneeId,
                    cancellationToken
                );

                if (!workloadResult.IsWithinLimits)
                {
                    return ValidationResult.Fail(
                        "Workload",
                        "Assignee has exceeded workload limits"
                    );
                }

                var skillResult = await _skillMatchRepository.ValidateSkillRequirementsAsync(
                    taskId,
                    assigneeId,
                    cancellationToken
                );

                if (!skillResult.MeetsRequirements)
                {
                    return ValidationResult.Fail(
                        "Skills",
                        "Assignee does not meet skill requirements"
                    );
                }

                return ValidationResult.Success();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error validating assignment for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:ValidateAssignment",
                    "Failed to validate assignment",
                    ex
                );
            }
        }

        public async Task<WorkloadImpact> CalculateWorkloadImpactAsync(
            Guid taskId,
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var currentWorkload = await _workloadRepository.GetCurrentWorkloadAsync(
                    assigneeId,
                    cancellationToken
                );

                var taskEstimate = await _delegatedTaskRepository.GetTaskEstimateAsync(
                    taskId,
                    cancellationToken
                );

                return new WorkloadImpact(
                    taskEstimate.EstimatedUtilization,
                    taskEstimate.Duration,
                    new List<Guid> { taskEstimate.ProjectId.GetValueOrDefault() },
                    currentWorkload.UtilizationRate
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error calculating workload impact for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:CalculateWorkloadImpact",
                    "Failed to calculate workload impact",
                    ex
                );
            }
        }

        public async Task<SkillMatchResult> AssessSkillMatchAsync(
            Guid taskId,
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                return await _skillMatchRepository.AssessSkillMatchAsync(
                    taskId,
                    assigneeId,
                    cancellationToken
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error assessing skill match for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:AssessSkillMatch",
                    "Failed to assess skill match",
                    ex
                );
            }
        }

        public async Task<PerformanceReport> GeneratePerformanceReportAsync(
            Guid assigneeId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var completedTasks = await _delegatedTaskRepository.GetCompletedTasksAsync(
                    assigneeId,
                    cancellationToken
                );

                return new PerformanceReport(
                    assigneeId,
                    completedTasks.Select(t => t.PerformanceMetrics).ToList()
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error generating performance report for user {UserId}", assigneeId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:GeneratePerformanceReport",
                    "Failed to generate performance report",
                    ex
                );
            }
        }

        public async Task<EscalationResult> HandleEscalationsAsync(
            Guid taskId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var task = await _delegatedTaskRepository.GetAsync(
                    taskId,
                    cancellationToken
                );

                if (task == null)
                {
                    throw new TaskNotFoundException(taskId);
                }

                var escalationRules = task.EscalationRules
                    .Where(r => EscalationPolicies.AutoEscalationPolicy.ShouldAutoEscalate(task, r))
                    .ToList();

                foreach (var rule in escalationRules)
                {
                    await _eventBus.PublishAsync(
                        new TaskEscalatedEto
                        {
                            TaskId = taskId,
                            AssigneeUserId = task.Assignee.UserId,
                            EscalationReason = rule.Condition,
                            EscalationLevel = rule.EscalationLevel,
                            DelegationId = task.Id,
                            TenantId = task.TenantId
                        },
                        cancellationToken: cancellationToken
                    );
                }

                return new EscalationResult(
                    escalationRules.Count > 0,
                    escalationRules
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error handling escalations for task {TaskId}", taskId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:HandleEscalations",
                    "Failed to handle escalations",
                    ex
                );
            }
        }

        public async Task<WorkloadOptimization> OptimizeWorkloadDistributionAsync(
            Guid projectId,
            CancellationToken cancellationToken = default)
        {
            try
            {
                var assignments = await _delegatedTaskRepository.GetProjectAssignmentsAsync(
                    projectId,
                    cancellationToken
                );

                var teamWorkloads = await _workloadRepository.GetProjectTeamWorkloadsAsync(
                    projectId,
                    cancellationToken
                );

                // Create optimization analysis
                var optimization = AnalyzeWorkloadDistribution(assignments, teamWorkloads);

                // Generate recommendations if needed
                if (optimization.IsImbalanced)
                {
                    var recommendations = GenerateOptimizationRecommendations(
                        assignments, 
                        teamWorkloads
                    );

                    return new WorkloadOptimization(
                        optimization,
                        recommendations
                    );
                }

                return new WorkloadOptimization(
                    optimization,
                    new List<AssignmentRecommendation>()
                );
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error optimizing workload for project {ProjectId}", projectId);
                throw new TaskDelegationDomainException(
                    "TaskDelegation:OptimizeWorkload",
                    "Failed to optimize workload distribution",
                    ex
                );
            }
        }

        private WorkloadDistributionAnalysis AnalyzeWorkloadDistribution(
            List<CurrentAssignment> assignments,
            List<TeamWorkload> teamWorkloads)
        {
            var averageUtilization = teamWorkloads.Average(w => w.UtilizationRate);
            var standardDeviation = CalculateStandardDeviation(
                teamWorkloads.Select(w => w.UtilizationRate)
            );

            var overutilizedUsers = teamWorkloads
                .Where(w => w.UtilizationRate > averageUtilization + standardDeviation)
                .Select(w => w.UserId)
                .ToList();

            var underutilizedUsers = teamWorkloads
                .Where(w => w.UtilizationRate < averageUtilization - standardDeviation)
                .Select(w => w.UserId)
                .ToList();

            return new WorkloadDistributionAnalysis(
                averageUtilization,
                standardDeviation,
                standardDeviation > WorkloadDistributionConsts.BalanceThreshold,
                overutilizedUsers,
                underutilizedUsers
            );
        }

        private List<AssignmentRecommendation> GenerateOptimizationRecommendations(
            List<CurrentAssignment> assignments,
            List<TeamWorkload> teamWorkloads)
        {
            var recommendations = new List<AssignmentRecommendation>();

            // Get overutilized users
            var analysis = AnalyzeWorkloadDistribution(assignments, teamWorkloads);

            if (!analysis.IsImbalanced)
            {
                return recommendations;
            }

            // For each overutilized user, find tasks that could be reassigned
            foreach (var userId in analysis.OverutilizedUsers)
            {
                var userAssignments = assignments
                    .Where(a => a.AssigneeId == userId)
                    .OrderBy(a => a.Priority) // Lower priority first
                    .ToList();

                // Find suitable assignees among underutilized users
                var potentialAssignees = teamWorkloads
                    .Where(w => analysis.UnderutilizedUsers.Contains(w.UserId))
                    .OrderBy(w => w.UtilizationRate) // Least utilized first
                    .ToList();

                // Try to balance workload by reassigning tasks
                foreach (var assignment in userAssignments)
                {
                    foreach (var newAssignee in potentialAssignees)
                    {
                        // Check if reassignment would improve balance
                        var currentAssigneeWorkload = teamWorkloads
                            .First(w => w.UserId == userId);

                        var newUtilizationCurrent = currentAssigneeWorkload.UtilizationRate - 
                                                  assignment.TaskUtilization;
                        var newUtilizationNew = newAssignee.UtilizationRate + 
                                              assignment.TaskUtilization;

                        // Add recommendation if it improves balance
                        if (Math.Abs(newUtilizationCurrent - newUtilizationNew) < 
                            Math.Abs(currentAssigneeWorkload.UtilizationRate - newAssignee.UtilizationRate))
                        {
                            recommendations.Add(new AssignmentRecommendation(
                                assignment.TaskId,
                                userId,
                                newAssignee.UserId,
                                assignment.TaskUtilization,
                                "Workload balancing",
                                CalculateImprovementScore(
                                    currentAssigneeWorkload.UtilizationRate, 
                                    newAssignee.UtilizationRate,
                                    newUtilizationCurrent,
                                    newUtilizationNew
                                )
                            ));

                            // Update workload for next iteration
                            newAssignee.UtilizationRate = newUtilizationNew;
                            break;
                        }
                    }
                }
            }

            // Return recommendations sorted by improvement score
            return recommendations
                .OrderByDescending(r => r.ImprovementScore)
                .ToList();
        }

        private double CalculateStandardDeviation(IEnumerable<double> values)
        {
            var avg = values.Average();
            var variance = values.Sum(v => Math.Pow(v - avg, 2)) / values.Count();
            return Math.Sqrt(variance);
        }

        private double CalculateImprovementScore(
            double currentAssigneeUtilization,
            double newAssigneeUtilization,
            double afterCurrentUtilization,
            double afterNewUtilization)
        {
            var beforeDifference = Math.Abs(currentAssigneeUtilization - newAssigneeUtilization);
            var afterDifference = Math.Abs(afterCurrentUtilization - afterNewUtilization);

            return (beforeDifference - afterDifference) / beforeDifference * 100;
        }
    }
}

