namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Value object that represents a performance report.
    /// </summary>
    public class PerformanceReport : ValueObject
    {
        public Guid UserId { get; private set; }
        public List<PerformanceMetrics> Metrics { get; private set; }
        public double AverageCompletionRate { get; private set; }
        public double AverageQualityScore { get; private set; }
        public TimeSpan AverageResponseTime { get; private set; }
        public PerformanceRating OverallRating { get; private set; }
        public List<string> Recommendations { get; private set; }

        private PerformanceReport() 
        {
            Metrics = new List<PerformanceMetrics>();
            Recommendations = new List<string>();
        }

        public PerformanceReport(
            Guid userId,
            List<PerformanceMetrics> metrics)
        {
            UserId = userId;
            Metrics = metrics ?? new List<PerformanceMetrics>();
            CalculateAverages();
            DetermineOverallRating();
            GenerateRecommendations();
        }

        private void CalculateAverages()
        {
            if (!Metrics.Any())
            {
                AverageCompletionRate = 0;
                AverageQualityScore = 0;
                AverageResponseTime = TimeSpan.Zero;
                return;
            }

            AverageCompletionRate = Metrics.Average(m => m.CompletionRate);
            AverageQualityScore = Metrics.Average(m => m.QualityScore);
            AverageResponseTime = TimeSpan.FromTicks(
                (long)Metrics.Average(m => m.ResponseTime.Ticks)
            );
        }

        private void DetermineOverallRating()
        {
            if (!Metrics.Any())
            {
                OverallRating = PerformanceRating.Satisfactory;
                return;
            }

            var ratings = Metrics.Select(m => m.CalculateOverallRating()).ToList();
            int excellentCount = ratings.Count(r => r == PerformanceRating.Excellent);
            int goodCount = ratings.Count(r => r == PerformanceRating.Good);
            int satisfactoryCount = ratings.Count(r => r == PerformanceRating.Satisfactory);
            int needsImprovementCount = ratings.Count(r => r == PerformanceRating.NeedsImprovement);

            // Determine predominant rating
            OverallRating = PerformanceRating.Satisfactory;

            if (excellentCount >= ratings.Count / 2) OverallRating = PerformanceRating.Excellent;
            else if (goodCount >= ratings.Count / 2) OverallRating = PerformanceRating.Good;
            else if (needsImprovementCount >= ratings.Count / 3) OverallRating = PerformanceRating.NeedsImprovement;
        }

        private void GenerateRecommendations()
        {
            Recommendations = new List<string>();

            if (!Metrics.Any()) return;

            // Add recommendations based on metrics
            if (AverageCompletionRate < PerformanceThresholdPolicies.CompletionRatePolicy.MinimumAcceptableCompletionRate)
            {
                Recommendations.Add("Improve task completion rate to meet target levels.");
            }

            if (AverageQualityScore < PerformanceThresholdPolicies.QualityPolicy.MinimumQualityScore)
            {
                Recommendations.Add("Focus on improving work quality metrics.");
            }

            if (AverageResponseTime > PerformanceThresholdPolicies.ResponseTimePolicy.MaxAcceptableResponseTime)
            {
                Recommendations.Add("Reduce response time to improve overall responsiveness.");
            }

            // Add specific recommendations based on overall rating
            switch (OverallRating)
            {
                case PerformanceRating.NeedsImprovement:
                    Recommendations.Add("Consider additional training or guidance to improve performance.");
                    break;
                case PerformanceRating.Satisfactory:
                    Recommendations.Add("Maintain consistent performance while seeking areas for improvement.");
                    break;
                case PerformanceRating.Good:
                    Recommendations.Add("Continue strong performance and mentor others in best practices.");
                    break;
                case PerformanceRating.Excellent:
                    Recommendations.Add("Share techniques and practices with team members to elevate team performance.");
                    break;
            }
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return UserId;
            foreach (var metric in Metrics)
            {
                yield return metric;
            }
            yield return AverageCompletionRate;
            yield return AverageQualityScore;
            yield return AverageResponseTime;
            yield return OverallRating;
            foreach (var recommendation in Recommendations)
            {
                yield return recommendation;
            }
        }
    }
}
