// File: NouAssist.Productivity.TaskProjectGTD.TaskDelegation/Domain/Factories/DelegatedTaskFactory.cs
namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.Factories
{
    /// <summary>
    /// Factory for creating DelegatedTask aggregates.
    /// </summary>
    public class DelegatedTaskFactory : IDomainService
    {
        private readonly IGuidGenerator _guidGenerator;
        private readonly ICurrentTenant _currentTenant;
        private readonly ITaskAssignmentService _taskAssignmentService;

        public DelegatedTaskFactory(
            IGuidGenerator guidGenerator,
            ICurrentTenant currentTenant,
            ITaskAssignmentService taskAssignmentService)
        {
            _guidGenerator = guidGenerator;
            _currentTenant = currentTenant;
            _taskAssignmentService = taskAssignmentService;
        }

        /// <summary>
        /// Creates a new DelegatedTask aggregate.
        /// </summary>
        public async Task<DelegatedTaskAggregate> AssignTaskAsync(
            Guid taskId,
            UserRef assignee,
            UserRef delegator,
            DateTimeOffset? dueDate,
            string notes,
            DelegationReason reason,
            DelegationPriority priority = DelegationPriority.Medium,
            CompetencyLevel competencyLevel = CompetencyLevel.Intermediate,
            CancellationToken cancellationToken = default)
        {
            // Validate assignment
            var validationResult = await _taskAssignmentService.ValidateAssignmentAsync(
                taskId, 
                assignee.UserId, 
                cancellationToken
            );

            if (!validationResult.IsValid)
            {
                throw new BusinessException(
                    "TaskDelegation:ValidationFailed",
                    "Failed to validate task assignment: " + 
                    string.Join(", ", validationResult.Errors.Select(e => e.Message))
                );
            }

            // Calculate workload impact
            var workloadImpact = await _taskAssignmentService.CalculateWorkloadImpactAsync(
                taskId, 
                assignee.UserId, 
                cancellationToken
            );

            if (workloadImpact.RiskLevel == RiskLevel.High)
            {
                throw new WorkloadExceededException(
                    assignee.UserId,
                    workloadImpact.ProjectedUtilization,
                    "Assigning this task would exceed user's workload capacity"
                );
            }

            // Create the aggregate
            var delegatedTask = new DelegatedTaskAggregate(
                _guidGenerator.Create(),
                taskId,
                assignee,
                delegator,
                dueDate,
                notes,
                reason,
                priority,
                competencyLevel,
                _currentTenant.Id
            );

            // Set acceptance deadline (24 hours from now by default)
            delegatedTask.SetAcceptanceDeadline(DateTimeOffset.UtcNow.AddHours(24));

            // Update workload impact
            delegatedTask.UpdateWorkloadImpact(workloadImpact);

            return delegatedTask;
        }

        /// <summary>
        /// Creates a new DelegatedTask for a set of multiple tasks with the same assignee.
        /// </summary>
        public async Task<List<DelegatedTaskAggregate>> BatchAssignTasksAsync(
            List<Guid> taskIds,
            UserRef assignee,
            UserRef delegator,
            DateTimeOffset? dueDate,
            string notes,
            DelegationReason reason,
            DelegationPriority priority = DelegationPriority.Medium,
            CompetencyLevel competencyLevel = CompetencyLevel.Intermediate,
            CancellationToken cancellationToken = default)
        {
            if (taskIds == null || !taskIds.Any())
            {
                throw new ArgumentException("At least one task ID must be provided", nameof(taskIds));
            }

            var delegatedTasks = new List<DelegatedTaskAggregate>();

            // Pre-validate the assignee's workload capacity for all tasks
            // This could be optimized with a batch validation method in a real implementation
            double cumulativeUtilization = 0;

            foreach (var taskId in taskIds)
            {
                var workloadImpact = await _taskAssignmentService.CalculateWorkloadImpactAsync(
                    taskId, 
                    assignee.UserId, 
                    cancellationToken
                );

                cumulativeUtilization += workloadImpact.ExpectedUtilizationIncrease;

                if (workloadImpact.CurrentUtilization + cumulativeUtilization > 100)
                {
                    throw new WorkloadExceededException(
                        assignee.UserId,
                        workloadImpact.CurrentUtilization + cumulativeUtilization,
                        "Assigning these tasks would exceed user's workload capacity"
                    );
                }
            }

            // Create delegated tasks for each task ID
            foreach (var taskId in taskIds)
            {
                var delegatedTask = new DelegatedTaskAggregate(
                    _guidGenerator.Create(),
                    taskId,
                    assignee,
                    delegator,
                    dueDate,
                    notes,
                    reason,
                    priority,
                    competencyLevel,
                    _currentTenant.Id
                );

                // Set acceptance deadline (24 hours from now by default)
                delegatedTask.SetAcceptanceDeadline(DateTimeOffset.UtcNow.AddHours(24));

                delegatedTasks.Add(delegatedTask);
            }

            return delegatedTasks;
        }
    }
}
