namespace NouAssist.Productivity.TaskProjectGTD.TaskDelegation.Domain.ValueObjects
{
    /// <summary>
    /// Value object that represents the result of a skill match assessment.
    /// </summary>
    public class SkillMatchResult : ValueObject
    {
        public Guid UserId { get; private set; }
        public Guid TaskId { get; private set; }
        public IReadOnlyList<SkillMatch> SkillMatches { get; private set; }
        public double OverallMatchPercentage { get; private set; }
        public bool IsCompleteMatch { get; private set; }

        private SkillMatchResult() { }

        public SkillMatchResult(
            Guid userId,
            Guid taskId,
            IEnumerable<SkillMatch> skillMatches)
        {
            UserId = userId;
            TaskId = taskId;
            SkillMatches = skillMatches.ToList().AsReadOnly();

            CalculateMatchResults();
        }

        private void CalculateMatchResults()
        {
            if (!SkillMatches.Any())
            {
                OverallMatchPercentage = 0;
                IsCompleteMatch = false;
                return;
            }

            // Calculate weighted match percentage
            var totalWeight = SkillMatches.Sum(m => GetPriorityWeight(m.Requirement.Priority));
            var weightedSum = SkillMatches.Sum(m => 
                GetPriorityWeight(m.Requirement.Priority) * CalculateMatchPercentage(m));

            OverallMatchPercentage = weightedSum / totalWeight;

            // Check if all must-have skills match
            IsCompleteMatch = !SkillMatches
                .Where(m => m.Requirement.Priority == RequirementPriority.Must)
                .Any(m => !m.IsMatch);
        }

        private double GetPriorityWeight(RequirementPriority priority)
        {
            return priority switch
            {
                RequirementPriority.Must => 3.0,
                RequirementPriority.Should => 2.0,
                RequirementPriority.Nice => 1.0,
                _ => 1.0
            };
        }

        private double CalculateMatchPercentage(SkillMatch match)
        {
            if (!match.HasSkill) return 0;

            var requiredLevel = (int)match.Requirement.RequiredLevel;
            var actualLevel = (int)match.ActualLevel;

            if (actualLevel >= requiredLevel) return 100;

            // Calculate partial match percentage based on how close the actual level is to required
            return (actualLevel * 100.0) / requiredLevel;
        }

        public List<SkillMatch> GetMissingCriticalSkills()
        {
            return SkillMatches
                .Where(m => m.Requirement.Priority == RequirementPriority.Must && !m.IsMatch)
                .ToList();
        }

        protected override IEnumerable<object> GetAtomicValues()
        {
            yield return UserId;
            yield return TaskId;
            foreach (var match in SkillMatches)
            {
                yield return match;
            }
            yield return OverallMatchPercentage;
            yield return IsCompleteMatch;
        }
    }
}

